"""Public tests use generated bytes and synthetic metadata; never game inputs."""

import hashlib
import copy
import io
import json
from pathlib import Path
import stat
import tempfile
import unittest
from unittest.mock import patch

from importers.cli import intake, validate_level, _download


class IntakeTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="lhr-intake-", dir="/tmp")
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)
        self.source = self.root / "synthetic-source.bin"
        self.payload = bytes(range(256)) * 17 + b"synthetic fixture, not original data"
        self.source.write_bytes(self.payload)
        self.private = self.root / "private"

    def ingest(self, **kwargs):
        return intake(kind="pc", edition="synthetic-test", local_path=self.source,
                      private_root=self.private, **kwargs)

    def test_manifest_records_bytes_and_edition_without_source(self):
        result = self.ingest()
        self.assertEqual(result["schema"], "lhr-input-v1")
        self.assertEqual(result["kind"], "pc")
        self.assertEqual(result["edition"], "synthetic-test")
        self.assertEqual(result["sha256"], hashlib.sha256(self.payload).hexdigest())
        self.assertEqual(result["size"], len(self.payload))
        self.assertNotIn(str(self.source), json.dumps(result))

    def test_preserved_copy_is_complete_and_read_only(self):
        mode_before = self.source.stat().st_mode
        result = self.ingest()
        copy = self.private / result["original"]
        self.assertEqual(copy.read_bytes(), self.payload)
        self.assertEqual(copy.stat().st_mode & (stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH), 0)
        self.assertEqual(self.source.read_bytes(), self.payload)
        self.assertEqual(self.source.stat().st_mode, mode_before)

    def test_repeated_intake_preserves_identity(self):
        first = self.ingest()
        second = self.ingest()
        for field in ("schema", "sha256", "original", "size", "kind", "edition"):
            self.assertEqual(first[field], second[field])
        self.assertEqual((self.private / first["original"]).read_bytes(), self.payload)

    def test_missing_local_input_fails(self):
        with self.assertRaises((ValueError, FileNotFoundError)):
            intake(kind="pc", edition="synthetic", local_path=self.root / "missing.bin",
                   private_root=self.private)

    def test_directory_input_fails(self):
        with self.assertRaises((ValueError, IsADirectoryError)):
            intake(kind="pc", edition="synthetic", local_path=self.root,
                   private_root=self.private)

    def test_unknown_kind_fails(self):
        with self.assertRaises(ValueError):
            intake(kind="other", edition="synthetic", local_path=self.source,
                   private_root=self.private)

    def test_repository_private_root_is_rejected(self):
        checkout = Path(__file__).resolve().parents[1]
        with self.assertRaises(ValueError):
            intake(kind="pc", edition="synthetic", local_path=self.source,
                   private_root=checkout / "must-not-create-private-test")
        self.assertFalse((checkout / "must-not-create-private-test").exists())

    def test_corrupted_preserved_original_is_detected(self):
        result = self.ingest()
        original = self.private / result["original"]
        original.chmod(0o600)
        original.write_bytes(b"tampered synthetic fixture")
        with self.assertRaises(ValueError):
            self.ingest()


class SyntheticDownloadTests(unittest.TestCase):
    """Mock transport only; exercise the real resume/write/hash intake pipeline."""

    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="lhr-download-", dir="/tmp")
        self.addCleanup(self.temporary.cleanup)
        self.downloads = Path(self.temporary.name)
        self.url = "https://synthetic.invalid/fixture"
        key = hashlib.sha256(self.url.encode()).hexdigest()
        self.partial = self.downloads / (key + ".part")
        self.state = self.downloads / (key + ".json")

    def download(self, data, status, headers):
        response = io.BytesIO(data)
        response.status = status
        response.headers = headers
        with patch("importers.cli.urllib.request.build_opener") as factory:
            factory.return_value.open.return_value = response
            path = _download(self.url, self.downloads)
            self.request = factory.return_value.open.call_args.args[0]
            return path

    def seed_partial(self):
        self.partial.write_bytes(b"ABC")
        self.state.write_text(json.dumps({"etag": '"fixture-v1"'}))

    def test_full_download_replaces_unvalidated_partial(self):
        self.partial.write_bytes(b"stale")
        path = self.download(b"ABCDEF", 200, {"Content-Length": "6", "ETag": '"fixture-v1"'})
        self.assertEqual(path.read_bytes(), b"ABCDEF")
        self.assertFalse(self.request.has_header("Range"))

    def test_validated_resume_preserves_prefix(self):
        self.seed_partial()
        path = self.download(b"DEF", 206, {"Content-Range": "bytes 3-5/6", "ETag": '"fixture-v1"'})
        self.assertEqual(path.read_bytes(), b"ABCDEF")
        self.assertEqual(self.request.get_header("Range"), "bytes=3-")
        self.assertEqual(self.request.get_header("If-range"), '"fixture-v1"')

    def test_ignored_resume_replaces_partial(self):
        self.seed_partial()
        path = self.download(b"NEW", 200, {"Content-Length": "3", "ETag": '"fixture-v2"'})
        self.assertEqual(path.read_bytes(), b"NEW")

    def test_changed_entity_or_wrong_range_is_rejected(self):
        for headers in ({"Content-Range": "bytes 3-5/6", "ETag": '"fixture-v2"'},
                        {"Content-Range": "bytes 0-2/6", "ETag": '"fixture-v1"'}):
            with self.subTest(headers=headers):
                self.seed_partial()
                with self.assertRaises(ValueError):
                    self.download(b"DEF", 206, headers)
                self.assertEqual(self.partial.read_bytes(), b"ABC")

    def test_truncated_response_is_retained_but_not_accepted(self):
        with self.assertRaises(ValueError):
            self.download(b"ABC", 200, {"Content-Length": "6", "ETag": '"fixture-v1"'})
        self.assertEqual(self.partial.read_bytes(), b"ABC")


class LevelTests(unittest.TestCase):
    def setUp(self):
        self.level = {
            "schema": "lhr-level-v1", "source": "synthetic", "units": "meters",
            "axes": "right-handed-y-up", "metadata": {"fixture": True},
            "objects": [
                {"id": "building", "model": "models/building.glb",
                 "position": [10, 0, -4], "rotation_degrees": [0, 90, 0],
                 "scale": [1, 2, 1], "metadata": {"district": "fixture"}},
                {"id": "wall", "position": [0, 1, 0],
                 "collision": {"shape": "box", "size": [5, 2, 1]}},
            ],
        }

    def test_model_collision_transform_and_metadata_are_preserved(self):
        before = copy.deepcopy(self.level)
        result = validate_level(self.level)
        self.assertEqual(result, before)
        self.assertEqual(self.level, before)

    def test_invalid_coordinates_are_rejected(self):
        for invalid in (float("inf"), float("nan"), True, "1"):
            with self.subTest(coordinate=repr(invalid)):
                item = copy.deepcopy(self.level)
                item["objects"][0]["position"][1] = invalid
                with self.assertRaises(ValueError):
                    validate_level(item)

    def test_unsafe_model_paths_are_rejected(self):
        for path in ("/private/model.glb", "../model.glb", "models/../model.glb",
                     "models\\model.glb", "model.obj"):
            with self.subTest(path=path):
                item = copy.deepcopy(self.level)
                item["objects"][0]["model"] = path
                with self.assertRaises(ValueError):
                    validate_level(item)

    def test_duplicate_object_ids_are_rejected(self):
        self.level["objects"][1]["id"] = "building"
        with self.assertRaises(ValueError):
            validate_level(self.level)

    def test_nonpositive_dimensions_are_rejected(self):
        for key in ("scale", "collision"):
            with self.subTest(field=key):
                item = copy.deepcopy(self.level)
                if key == "scale":
                    item["objects"][0]["scale"] = [1, 0, 1]
                else:
                    item["objects"][1]["collision"]["size"] = [1, -1, 1]
                with self.assertRaises(ValueError):
                    validate_level(item)

    def test_unknown_fields_and_empty_objects_are_rejected(self):
        for location in ("root", "object", "empty"):
            with self.subTest(location=location):
                item = copy.deepcopy(self.level)
                if location == "root":
                    item["source_url"] = "https://invalid.example/private"
                elif location == "object":
                    item["objects"][0]["unexpected"] = 1
                else:
                    item["objects"][0].pop("model")
                with self.assertRaises(ValueError):
                    validate_level(item)

    def test_units_and_axes_are_explicit(self):
        for key, value in (("units", "centimeters"), ("axes", "left-handed-z-up")):
            with self.subTest(field=key):
                item = copy.deepcopy(self.level)
                item[key] = value
                with self.assertRaises(ValueError):
                    validate_level(item)


if __name__ == "__main__":
    unittest.main()
